// priority: 100
// Mundus Foci: custom items & blocks.
// Startup scripts only run when the game launches; /reload does NOT re-run them.
// Textures live in kubejs/assets/mundusfoci/textures and are generated by tools/gen_textures.py.
// Display names live in kubejs/assets/mundusfoci/lang/en_us.json.

StartupEvents.registry('item', event => {
  // Hearty Farmer's Delight cooking-pot meal (recipe in server_scripts/recipes.js).
  // The empty bowl is returned in server_scripts/events.js (ItemEvents.foodEaten).
  event.create('mundusfoci:hearth_stew')
    .maxStackSize(16)
    .food(food => {
      food.hunger(10)
      food.saturation(0.9)
      food.effect('minecraft:regeneration', 600, 0, 1.0) // 30 s
      food.effect('minecraft:absorption', 1200, 0, 1.0) // 60 s
    })

  // Cheap, fast-to-eat travel snack.
  event.create('mundusfoci:trail_mix')
    .food(food => {
      food.hunger(4)
      food.saturation(0.4)
      food.fastToEat()
      food.effect('minecraft:speed', 400, 0, 1.0) // 20 s
    })

  // Item magnet. Toggle with right-click; logic lives in server_scripts/events.js.
  event.create('mundusfoci:lodestone_charm')
    .maxStackSize(1)
    .rarity('uncommon')
})

StartupEvents.registry('block', event => {
  const HEARTH_TEX = 'mundusfoci:block/hearthstone_bricks'

  // Shared properties for the hearthstone family (roughly vanilla stone bricks).
  const stone = builder => builder
    .stoneSoundType()
    .hardness(1.5)
    .resistance(6.0)
    .requiresTool(true)
    .tagBlock('minecraft:mineable/pickaxe')

  stone(event.create('mundusfoci:hearthstone'))
  stone(event.create('mundusfoci:hearthstone_bricks'))
  stone(event.create('mundusfoci:chiseled_hearthstone'))

  stone(event.create('mundusfoci:hearthstone_brick_stairs', 'stairs'))
    .textureAll(HEARTH_TEX)
    .tagBoth('minecraft:stairs')
  stone(event.create('mundusfoci:hearthstone_brick_slab', 'slab'))
    .textureAll(HEARTH_TEX)
    .tagBoth('minecraft:slabs')
  stone(event.create('mundusfoci:hearthstone_brick_wall', 'wall'))
    .textureAll(HEARTH_TEX)
    .tagBoth('minecraft:walls')

  // Full-brightness decorative lamp.
  event.create('mundusfoci:hearth_lamp')
    .glassSoundType()
    .hardness(0.3)
    .resistance(0.3)
    .lightLevel(1.0)
    .tagBlock('minecraft:mineable/pickaxe')
})
